from tracker import BudgetTracker


class InputEnded(Exception):
    """Raised when stdin reaches EOF or the user interrupts input."""


def fmt(x):
    return f"${x:,.2f}"


def read_line(prompt):
    try:
        return input(prompt)
    except (EOFError, KeyboardInterrupt):
        raise InputEnded


