    while True:
        try:
            v = float(read_line(prompt))
            if v > 0:
                return round(v, 2)
            print("Amount must be positive.")
        except ValueError:
            print("Enter a valid number.")


def read_int(prompt, limit):
    while True:
        try:
            v = int(read_line(prompt))
            if 0 <= v < limit:
                return v
        except ValueError:
            pass
        print(f"Enter a number between 0 and {limit - 1}.")


