            elif choice == "8":
                show_goals(tracker)
            elif choice == "9":
                save_data(tracker.data)
                print("Data saved. Goodbye!")
                return
            else:
                print("Invalid choice, try again.")
    except InputEnded:
        save_data(tracker.data)
        print("\nInput ended. Data saved. Goodbye!")


if __name__ == "__main__":
